const RISK_HIGH = "#D6544A";
const RISK_MID = "#D9A441";
const RISK_LOW = "#4F9E6E";
const ACCENT = "#5FAFD7";

function riskColor(score) {
  if (score > 0.7) return RISK_HIGH;
  if (score > 0.4) return RISK_MID;
  return RISK_LOW;
}
function riskLabel(score) {
  if (score > 0.7) return "High";
  if (score > 0.4) return "Moderate";
  return "Low";
}
function fmtCr(n) {
  if (n == null) return "—";
  if (n >= 100000) return (n / 100000).toFixed(2) + "L Cr";
  return n.toLocaleString("en-IN", { maximumFractionDigits: 1 }) + " Cr";
}
function fmtPct(n, digits = 1) {
  if (n == null) return "—";
  const sign = n > 0 ? "+" : "";
  return sign + n.toFixed(digits) + "%";
}
function driverName(key) {
  const map = {
    agency_hist_overrun_pct: "Agency's cost-overrun track record",
    agency_hist_slippage_months: "Agency's schedule track record",
    sector_hist_overrun_pct: "Sector cost-overrun history",
    sector_hist_slippage_months: "Sector schedule history",
    ministry_hist_overrun_pct: "Ministry cost-overrun history",
    ministry_hist_slippage_months: "Ministry schedule history",
    approval_year: "Project age since approval",
    log_original_cost: "Project size (cost)",
    planned_duration_months: "Planned project duration",
    is_multi_state: "Spans multiple states",
  };
  if (map[key]) return map[key];
  if (key.startsWith("sector_")) return "Sector: " + key.replace("sector_", "");
  if (key.startsWith("ministry_")) return "Ministry: " + key.replace("ministry_", "");
  return key;
}

export default function Dashboard() {
  const [query, setQuery] = useState("");
  const [sortKey, setSortKey] = useState("orisk");
  const [selected, setSelected] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [chatInput, setChatInput] = useState("");
  const [chatLoading, setChatLoading] = useState(false);

  function openProject(p) {
    setSelected(p);
    setChatMessages([]);
    setChatInput("");
  }

  async function askAssistant() {
    const question = chatInput.trim();
    if (!question || !selected || chatLoading) return;
    const nextMessages = [...chatMessages, { role: "user", text: question }];
    setChatMessages(nextMessages);
    setChatInput("");
    setChatLoading(true);

    const contextData = {
      project: selected.n,
      agency: selected.ag,
      ministry: selected.mi,
      sector: selected.se,
      state: selected.st,
      original_cost_cr: selected.oc,
      cost_overrun_pct: selected.co,
      schedule_slippage_months: selected.ts,
      physical_progress_pct: selected.pp,
      cost_risk_score: selected.cr,
      time_risk_score: selected.tr,
      overall_risk_score: selected.orisk,
      top_cost_risk_drivers: selected.cd.map((d) => ({ factor: driverName(d[0]), shap_impact: d[1] })),
      top_schedule_risk_drivers: selected.td.map((d) => ({ factor: driverName(d[0]), shap_impact: d[1] })),
      nearest_comparable_project: selected.cp,
      comparable_agency: selected.ca,
      comparable_outcome: selected.con,
      comparable_cost_overrun_pct: selected.cco,
      comparable_schedule_slippage_months: selected.cts,
    };

    const systemPrompt =
      "You are a project-intelligence assistant inside a MoSPI infrastructure monitoring dashboard (PAIMANA early-warning system). " +
      "You must answer ONLY using the structured project data provided below — this is the model's own stored output for the currently selected project. " +
      "Never use outside knowledge about this project, this agency, or any other real-world project, even if you think you know something relevant. " +
      "If the question can't be answered from this data, say so plainly rather than guessing or generalizing. " +
      "Keep answers to 2-4 sentences, plain language suitable for a government official reviewing the project.\n\n" +
      "STRUCTURED PROJECT DATA:\n" + JSON.stringify(contextData, null, 2);

    try {
      const response = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          model: "claude-sonnet-4-6",
          max_tokens: 400,
          system: systemPrompt,
          messages: nextMessages.map((m) => ({ role: m.role, content: m.text })),
        }),
      });
      const data = await response.json();
      const text = (data.content || [])
        .filter((b) => b.type === "text")
        .map((b) => b.text)
        .join("\n") || "I wasn't able to generate a response from the project data.";
      setChatMessages((prev) => [...prev, { role: "assistant", text }]);
    } catch (err) {
      setChatMessages((prev) => [
        ...prev,
        { role: "assistant", text: "Assistant is unavailable right now — couldn't reach the model." },
      ]);
    } finally {
      setChatLoading(false);
    }
  }

  const rows = useMemo(() => {
    let r = DATA.top_risk_projects;
    if (query.trim()) {
      const q = query.toLowerCase();
      r = r.filter(
        (p) =>
          p.n.toLowerCase().includes(q) ||
          p.mi.toLowerCase().includes(q) ||
          p.se.toLowerCase().includes(q) ||
          p.st.toLowerCase().includes(q) ||
          (p.ag || "").toLowerCase().includes(q)
      );
    }
    r = [...r].sort((a, b) => b[sortKey] - a[sortKey]);
    return r;
  }, [query, sortKey]);

  const kpi = DATA.kpi;

  const sectorData = DATA.sector_chart.slice(0, 10).map((s) => ({
    name: s.sector.length > 22 ? s.sector.slice(0, 20) + "…" : s.sector,
    risk: s.avg_risk,
    count: s.count,
  }));

  const costCls = DATA.model_comparison.filter(
    (m) => m.task === "cost_overrun_classification"
  );
  const timeCls = DATA.model_comparison.filter(
    (m) => m.task === "time_overrun_classification"
  );

  return (
    <div className="dash">
      <style>{`
        .dash {
          background: #0B1420;
          color: #E9E6DC;
          font-family: 'IBM Plex Sans', ui-sans-serif, system-ui, sans-serif;
          min-height: 100vh;
          padding: 28px 32px 60px;
        }
        .mono { font-family: 'IBM Plex Mono', ui-monospace, monospace; }
        .topbar {
          display: flex;
          align-items: baseline;
          justify-content: space-between;
          border-bottom: 1px solid #24344A;
          padding-bottom: 18px;
          margin-bottom: 22px;
          flex-wrap: wrap;
          gap: 12px;
        }
        .brand { display:flex; flex-direction:column; gap:2px; }
        .brand-title {
          font-size: 20px;
          font-weight: 600;
          letter-spacing: 0.2px;
        }
        .brand-sub {
          font-size: 12.5px;
          color: #8B97A8;
        }
        .search {
          background: #121D2E;
          border: 1px solid #24344A;
          color: #E9E6DC;
          padding: 8px 12px;
          font-size: 13.5px;
          width: 300px;
          outline: none;
          font-family: 'IBM Plex Sans', sans-serif;
        }
        .search:focus { border-color: ${ACCENT}; }
        .search::placeholder { color: #5C6B7E; }

        .kpi-row {
          display: grid;
          grid-template-columns: repeat(5, 1fr);
          border: 1px solid #24344A;
          margin-bottom: 26px;
        }
        .kpi {
          padding: 16px 18px;
          border-right: 1px solid #24344A;
        }
        .kpi:last-child { border-right: none; }
        .kpi-value {
          font-size: 26px;
          font-weight: 600;
        }
        .kpi-label {
          font-size: 12px;
          color: #8B97A8;
          margin-top: 4px;
        }

        .section-title {
          font-size: 15px;
          font-weight: 600;
          margin-bottom: 12px;
          color: #E9E6DC;
        }
        .section-sub {
          font-size: 12px;
          color: #8B97A8;
          margin-top: -8px;
          margin-bottom: 14px;
        }

        .analytics-row {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 24px;
          margin-bottom: 30px;
        }
        .panel {
          border: 1px solid #24344A;
          background: #0E1826;
          padding: 18px 20px;
        }

        .compare-grid {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 14px;
        }
        .compare-card {
          border: 1px solid #24344A;
          padding: 12px 14px;
        }
        .compare-card h4 {
          font-size: 12px;
          font-weight: 500;
          color: #8B97A8;
          margin: 0 0 10px;
        }
        .compare-line {
          display: flex;
          justify-content: space-between;
          font-size: 13px;
          padding: 4px 0;
        }
        .compare-line .lbl { color: #8B97A8; }
        .compare-line .winner { color: ${RISK_LOW}; }

        table {
          width: 100%;
          border-collapse: collapse;
          font-size: 13px;
        }
        thead th {
          text-align: left;
          font-weight: 500;
          color: #8B97A8;
          font-size: 12px;
          padding: 8px 10px;
          border-bottom: 1px solid #24344A;
          cursor: pointer;
          user-select: none;
        }
        thead th.active { color: ${ACCENT}; }
        tbody td {
          padding: 9px 10px;
          border-bottom: 1px solid #182333;
          vertical-align: middle;
        }
        tbody tr { cursor: pointer; }
        tbody tr:hover { background: #121D2E; }
        .risk-pill {
          display: inline-flex;
          align-items: center;
          gap: 6px;
          font-size: 12.5px;
        }
        .risk-dot {
          width: 8px; height: 8px; border-radius: 50%;
          display: inline-block;
        }
        .proj-name { font-weight: 500; }
        .proj-meta { font-size: 11.5px; color: #8B97A8; margin-top: 2px; }

        .overlay {
          position: fixed; inset: 0;
          background: rgba(3,7,13,0.55);
          display: flex; justify-content: flex-end;
          z-index: 20;
        }
        .drawer {
          width: 460px;
          max-width: 92vw;
          background: #0E1826;
          border-left: 1px solid #24344A;
          padding: 26px 26px 40px;
          overflow-y: auto;
          box-shadow: -8px 0 28px rgba(0,0,0,0.4);
        }
        .drawer-close {
          background: none; border: 1px solid #24344A; color: #8B97A8;
          width: 28px; height: 28px; cursor: pointer; font-size: 14px;
          float: right;
        }
        .drawer h2 { font-size: 18px; margin: 6px 0 2px; line-height: 1.35; }
        .drawer .meta { font-size: 12.5px; color: #8B97A8; margin-bottom: 18px; }
        .stat-line {
          display: flex; justify-content: space-between;
          font-size: 13.5px; padding: 7px 0; border-bottom: 1px solid #182333;
        }
        .driver-bar-row { margin: 10px 0; }
        .driver-label { font-size: 12.5px; color: #C8CCD4; margin-bottom: 4px; }
        .driver-track { background: #182333; height: 6px; width: 100%; }
        .driver-fill { height: 6px; }
        .comparable-card {
          margin-top: 8px;
          border: 1px solid #24344A;
          padding: 12px 14px;
          background: #121D2E;
        }
        .chat-log {
          max-height: 220px;
          overflow-y: auto;
          display: flex;
          flex-direction: column;
          gap: 8px;
          margin-bottom: 10px;
        }
        .chat-empty {
          font-size: 12px;
          color: #5C6B7E;
          font-style: italic;
          padding: 6px 0;
        }
        .chat-bubble {
          font-size: 13px;
          line-height: 1.5;
          padding: 8px 10px;
          border: 1px solid #24344A;
          max-width: 92%;
        }
        .chat-user {
          align-self: flex-end;
          background: #14314A;
          border-color: #24506E;
        }
        .chat-assistant {
          align-self: flex-start;
          background: #121D2E;
        }
        .chat-loading { color: #8B97A8; font-style: italic; }
        .chat-input-row { display: flex; gap: 8px; }
        .chat-input { width: 100%; flex: 1; }
        .chat-send {
          background: ${ACCENT};
          border: none;
          color: #0B1420;
          font-weight: 600;
          font-size: 13px;
          padding: 0 16px;
          cursor: pointer;
        }
        .chat-send:disabled { opacity: 0.5; cursor: default; }

        @media (max-width: 900px) {
          .kpi-row { grid-template-columns: repeat(2, 1fr); }
          .analytics-row { grid-template-columns: 1fr; }
        }
      `}</style>

      <div className="topbar">
        <div className="brand">
          <div className="brand-title">PAIMANA Early-Warning Layer</div>
          <div className="brand-sub">Predictive risk overlay · SIH26103 prototype · April 2026 snapshot</div>
        </div>
        <input
          className="search"
          placeholder="Search project, ministry, sector, state, agency…"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
      </div>

      <div className="kpi-row">
        <div className="kpi">
          <div className="kpi-value mono">{kpi.total_projects.toLocaleString("en-IN")}</div>
          <div className="kpi-label">Projects tracked</div>
        </div>
        <div className="kpi">
          <div className="kpi-value mono">{fmtCr(kpi.total_cost_cr)}</div>
          <div className="kpi-label">Original cost, portfolio</div>
        </div>
        <div className="kpi">
          <div className="kpi-value mono" style={{ color: RISK_HIGH }}>{kpi.high_risk_count}</div>
          <div className="kpi-label">High-risk projects (&gt;70%)</div>
        </div>
        <div className="kpi">
          <div className="kpi-value mono">{fmtPct(kpi.avg_cost_overrun_pct)}</div>
          <div className="kpi-label">Avg cost overrun</div>
        </div>
        <div className="kpi">
          <div className="kpi-value mono">{kpi.avg_slippage_months.toFixed(1)}mo</div>
          <div className="kpi-label">Avg schedule slippage</div>
        </div>
      </div>

      <div className="analytics-row">
        <div className="panel">
          <div className="section-title">Average risk by sector</div>
          <div className="section-sub">Top 10 sectors by predicted risk score</div>
          <ResponsiveContainer width="100%" height={260}>
            <BarChart data={sectorData} layout="vertical" margin={{ left: 10, right: 20 }}>
              <CartesianGrid strokeDasharray="3 3" stroke="#182333" horizontal={false} />
              <XAxis type="number" domain={[0, 1]} tick={{ fill: "#8B97A8", fontSize: 11 }} />
              <YAxis type="category" dataKey="name" width={150} tick={{ fill: "#C8CCD4", fontSize: 11.5 }} />
              <Tooltip
                contentStyle={{ background: "#121D2E", border: "1px solid #24344A", fontSize: 12 }}
                formatter={(v, n) => (n === "risk" ? [v.toFixed(2), "Avg risk score"] : [v, n])}
              />
              <Bar dataKey="risk" radius={[0, 2, 2, 0]}>
                {sectorData.map((s, i) => (
                  <Cell key={i} fill={riskColor(s.risk)} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>

        <div className="panel">
          <div className="section-title">Statistics vs. ML — measured, not asserted</div>
          <div className="section-sub">Classification: is a project at risk of overrun? (CUF+extra features)</div>
          <div className="compare-grid">
            <div className="compare-card">
              <h4>Cost-overrun risk</h4>
              {costCls.filter(c => c.feature_set === "CUF+extra").map((c, i) => (
                <React.Fragment key={i}>
                  <div className="compare-line"><span className="lbl">Baseline AUC</span><span className="mono">{c.baseline_auc}</span></div>
                  <div className="compare-line"><span className="lbl">ML (XGBoost) AUC</span><span className="mono winner">{c.ml_auc}</span></div>
                </React.Fragment>
              ))}
            </div>
            <div className="compare-card">
              <h4>Time-overrun risk</h4>
              {timeCls.filter(c => c.feature_set === "CUF+extra").map((c, i) => (
                <React.Fragment key={i}>
                  <div className="compare-line"><span className="lbl">Baseline AUC</span><span className="mono">{c.baseline_auc}</span></div>
                  <div className="compare-line"><span className="lbl">ML (XGBoost) AUC</span><span className="mono winner">{c.ml_auc}</span></div>
                </React.Fragment>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="section-title">Risk watchlist</div>
      <div className="section-sub">Top 200 projects by combined risk score · click a row for the full breakdown · {rows.length} shown</div>

      <table>
        <thead>
          <tr>
            <th onClick={() => setSortKey("orisk")} className={sortKey === "orisk" ? "active" : ""}>Risk</th>
            <th>Project</th>
            <th onClick={() => setSortKey("oc")} className={sortKey === "oc" ? "active" : ""}>Original cost</th>
            <th onClick={() => setSortKey("co")} className={sortKey === "co" ? "active" : ""}>Cost overrun</th>
            <th onClick={() => setSortKey("ts")} className={sortKey === "ts" ? "active" : ""}>Slippage</th>
            <th onClick={() => setSortKey("pp")} className={sortKey === "pp" ? "active" : ""}>Progress</th>
          </tr>
        </thead>
        <tbody>
          {rows.slice(0, 60).map((p) => (
            <tr key={p.c} onClick={() => openProject(p)}>
              <td>
                <span className="risk-pill">
                  <span className="risk-dot" style={{ background: riskColor(p.orisk) }} />
                  <span className="mono">{(p.orisk * 100).toFixed(0)}%</span>
                </span>
              </td>
              <td>
                <div className="proj-name">{p.n.length > 55 ? p.n.slice(0, 53) + "…" : p.n}</div>
                <div className="proj-meta">{p.mi} · {p.st}</div>
              </td>
              <td className="mono">{fmtCr(p.oc)}</td>
              <td className="mono" style={{ color: p.co > 10 ? RISK_HIGH : p.co > 0 ? RISK_MID : "#8B97A8" }}>
                {fmtPct(p.co)}
              </td>
              <td className="mono" style={{ color: p.ts > 6 ? RISK_HIGH : p.ts > 0 ? RISK_MID : "#8B97A8" }}>
                {p.ts > 0 ? "+" : ""}{p.ts.toFixed(1)}mo
              </td>
              <td className="mono">{p.pp != null ? p.pp.toFixed(0) + "%" : "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {selected && (
        <div className="overlay" onClick={() => setSelected(null)}>
          <div className="drawer" onClick={(e) => e.stopPropagation()}>
            <button className="drawer-close" onClick={() => setSelected(null)}>✕</button>
            <h2>{selected.n}</h2>
            <div className="meta">{selected.ag} · {selected.mi} · {selected.st}</div>

            <div className="stat-line"><span>Original cost</span><span className="mono">{fmtCr(selected.oc)}</span></div>
            <div className="stat-line"><span>Cost overrun</span><span className="mono" style={{ color: riskColor(selected.cr) }}>{fmtPct(selected.co)}</span></div>
            <div className="stat-line"><span>Schedule slippage</span><span className="mono" style={{ color: riskColor(selected.tr) }}>{selected.ts > 0 ? "+" : ""}{selected.ts.toFixed(1)} months</span></div>
            <div className="stat-line"><span>Physical progress</span><span className="mono">{selected.pp != null ? selected.pp.toFixed(0) + "%" : "—"}</span></div>
            <div className="stat-line"><span>Overall risk</span><span className="mono" style={{ color: riskColor(selected.orisk) }}>{riskLabel(selected.orisk)} ({(selected.orisk * 100).toFixed(0)}%)</span></div>

            <div style={{ marginTop: 20 }}>
              <div className="section-title" style={{ fontSize: 13 }}>Top drivers — cost risk</div>
              {selected.cd.map((d, i) => {
                const mag = Math.min(Math.abs(d[1]) / 2, 1);
                return (
                  <div className="driver-bar-row" key={i}>
                    <div className="driver-label">{driverName(d[0])}</div>
                    <div className="driver-track">
                      <div className="driver-fill" style={{ width: `${mag * 100}%`, background: d[1] > 0 ? RISK_HIGH : RISK_LOW }} />
                    </div>
                  </div>
                );
              })}
            </div>

            <div style={{ marginTop: 18 }}>
              <div className="section-title" style={{ fontSize: 13 }}>Top drivers — schedule risk</div>
              {selected.td.map((d, i) => {
                const mag = Math.min(Math.abs(d[1]) / 2, 1);
                return (
                  <div className="driver-bar-row" key={i}>
                    <div className="driver-label">{driverName(d[0])}</div>
                    <div className="driver-track">
                      <div className="driver-fill" style={{ width: `${mag * 100}%`, background: d[1] > 0 ? RISK_HIGH : RISK_LOW }} />
                    </div>
                  </div>
                );
              })}
            </div>

            {selected.cp && (
              <div className="comparable-card">
                <div style={{ fontSize: 12, color: "#8B97A8", marginBottom: 6 }}>Nearest comparable project</div>
                <div style={{ fontWeight: 500, marginBottom: 4 }}>{selected.cp}</div>
                <div style={{ fontSize: 12, color: "#8B97A8", marginBottom: 8 }}>{selected.ca}</div>
                <div className="stat-line" style={{ borderBottom: "none", padding: "3px 0" }}>
                  <span style={{ fontSize: 12.5 }}>Its outcome</span>
                  <span className="mono" style={{ fontSize: 12.5, color: selected.con === "Recovered / on track" ? RISK_LOW : RISK_HIGH }}>
                    {selected.con}
                  </span>
                </div>
                <div className="stat-line" style={{ borderBottom: "none", padding: "3px 0" }}>
                  <span style={{ fontSize: 12.5 }}>Cost overrun / slippage</span>
                  <span className="mono" style={{ fontSize: 12.5 }}>{fmtPct(selected.cco)} / {selected.cts > 0 ? "+" : ""}{selected.cts}mo</span>
                </div>
              </div>
            )}

            <div style={{ marginTop: 22 }}>
              <div className="section-title" style={{ fontSize: 13 }}>Ask about this project</div>
              <div className="section-sub" style={{ marginBottom: 10 }}>
                Answers are grounded only in this project's own model output — nothing free-generated.
              </div>
              <div className="chat-log">
                {chatMessages.length === 0 && (
                  <div className="chat-empty">
                    Try: "Why is this project risky?" or "What happened to the comparable project?"
                  </div>
                )}
                {chatMessages.map((m, i) => (
                  <div key={i} className={"chat-bubble " + (m.role === "user" ? "chat-user" : "chat-assistant")}>
                    {m.text}
                  </div>
                ))}
                {chatLoading && <div className="chat-bubble chat-assistant chat-loading">Thinking…</div>}
              </div>
              <div className="chat-input-row">
                <input
                  className="search chat-input"
                  placeholder="Ask a question about this project…"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && askAssistant()}
                />
                <button className="chat-send" onClick={askAssistant} disabled={chatLoading}>
                  Ask
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
